CustomField.formula:
/* IMGA LEVEL: Current record is IMGA - Just check GI */
IF(TEXT(IM_Hierarchy_Level__c) == "IM Group (IMGA)", Global_Account__c,

/* Country Parent Level: Parent is IMGA - Check GI first, then IMGA, then PD */
IF(Parent.Global_Account__c && TEXT(Parent.IM_Hierarchy_Level__c) == "IM Group (IMGA)",
    IF(TEXT(Parent.Program_Designation__c) == "Strategic Account",
        /* Strategic Account: Check Current Record for North America */
        IF(Territory_Region__c == "North America", Parent.Global_Account__c, FALSE),
        /* Must be explicitly 'Global Account' to flow directly */
        IF(TEXT(Parent.Program_Designation__c) == "Global Account", Parent.Global_Account__c, FALSE)
    ),

/* LEVEL 2: Parent is Country Parent */
IF(NOT(ISBLANK(ParentId)) && TEXT(Parent.Parent.IM_Hierarchy_Level__c) == "IM Group (IMGA)",
Parent.Global_Account__c,
FALSE)
)
)
